		type result struct {
			request *missingReferenceReleaseRequest
			handled bool
			err     error
		}
		results := make(chan result, 2)
		var workers sync.WaitGroup
		for i := 0; i < 2; i++ {
			workers.Add(1)
			go func() {
				defer workers.Done()
				req, handled, err := r.PrepareMissingReferenceRelease(ctx, c.usage.ID)
				results <- result{req, handled, err}
			}()
		}
		workers.Wait()
		close(results)
